  function stopCamera(){cameraStream?.getTracks().forEach(track=>track.stop());cameraStream=null;id('video').srcObject=null;id('video').style.display='none';id('videoEmpty').style.display='grid';id('videoLabel').textContent='林晓雨（我） · 摄像头未开启';id('cameraToggle').textContent='开启摄像头';id('cameraToggle').classList.remove('on')}
  async function startCamera(){id('cameraError').classList.remove('show');if(!navigator.mediaDevices?.getUserMedia){id('cameraError').textContent='当前浏览器不支持摄像头访问，请更换 Chrome、Edge 或 Safari 最新版本。';id('cameraError').classList.add('show');return}try{id('cameraToggle').disabled=true;cameraStream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});id('video').srcObject=cameraStream;id('video').style.display='block';id('videoEmpty').style.display='none';id('videoLabel').textContent='林晓雨（我） · 摄像头已开启';id('cameraToggle').textContent='关闭摄像头';id('cameraToggle').classList.add('on');toast('摄像头已开启，仅在本机预览')}catch(error){const denied=error.name==='NotAllowedError'||error.name==='SecurityError',missing=error.name==='NotFoundError'||error.name==='DevicesNotFoundError';id('cameraError').textContent=denied?'未获得摄像头权限。请点击浏览器地址栏旁的权限图标，允许摄像头访问后重试。':missing?'未检测到可用摄像头。请检查设备连接，或继续使用文字方式完成面试。':'摄像头暂时无法启用。请关闭其他占用摄像头的应用后重试。';id('cameraError').classList.add('show');stopCamera()}finally{id('cameraToggle').disabled=false}}
